/**
 * The shipped catalogue data (generated by scripts/library/generate_catalogue.py) must be consistent:
 * a size that bd_warehouse lists but cannot build must not be offered. The Python script
 * scripts/library/verify_catalogue.py builds every offered size for real; this test guards the data
 * that ships and the known cases.
 */
import { describe, expect, it } from 'vitest';
import catalogueText from './data/catalogue.json?raw';
import unbuildableText from './data/unbuildable.json?raw';
import { parseCatalogue, type CatalogueOption } from './catalogue.js';

const catalogue = parseCatalogue(JSON.parse(catalogueText));
const unbuildable = JSON.parse(unbuildableText) as {
  class: string;
  type: string | null;
  size: string;
  error: string;
}[];

type SizeOption = Extract<CatalogueOption, { kind: 'size' }>;

/** Every (type, size) a class offers. */
function offered(name: string): { type: string | null; size: string }[] {
  const o = catalogue.classes[name]?.options?.find((x): x is SizeOption => x.kind === 'size');
  if (!o) return [];
  return Array.isArray(o.sizes)
    ? (o.sizes as readonly string[]).map((size) => ({ type: null, size }))
    : Object.entries(o.sizes as Record<string, readonly string[]>).flatMap(([type, sizes]) =>
        sizes.map((size) => ({ type, size })),
      );
}

describe('shipped parts catalogue', () => {
  it('offers no size the library cannot build', () => {
    const bad = unbuildable.filter((u) =>
      offered(u.class).some((o) => o.size === u.size && (o.type === null || o.type === u.type)),
    );
    expect(bad).toEqual([]);
  });

  it('keeps the known unbuildable sizes out: ASME #0, #1 and #2 screws (KeyError in bd_warehouse 0.4.0)', () => {
    const sizes = offered('SocketHeadCapScrew').map((o) => o.size);
    for (const size of ['#0-80', '#1-64', '#1-72', '#2-56', '#2-64']) {
      expect(sizes, size).not.toContain(size);
    }
    // the smallest ASME size that works is still offered
    expect(sizes).toContain('#3-48');
    expect(unbuildable.map((u) => u.size)).toContain('#1-64');
  });

  it('still offers plenty of sizes for the common classes', () => {
    expect(offered('SocketHeadCapScrew').length).toBeGreaterThan(40);
    expect(offered('HexNut').length).toBeGreaterThan(40);
    expect(offered('SingleRowDeepGrooveBallBearing').length).toBeGreaterThan(20);
    expect(offered('ORing').length).toBeGreaterThan(100);
  });

  it('every type offered has sizes, and the type default is one of them', () => {
    for (const [name, c] of Object.entries(catalogue.classes)) {
      const size = c.options?.find((x): x is SizeOption => x.kind === 'size');
      if (!size || Array.isArray(size.sizes)) continue;
      const types = Object.keys(size.sizes);
      const typeOption = c.options?.find((x) => x.name === size.typeParam);
      if (typeOption?.kind === 'choice') {
        expect([...typeOption.choices].map(String).sort(), name).toEqual([...types].sort());
      }
    }
  });
});
